import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.BZO4qERu.js";const f=JSON.parse('{"title":"数据源","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/sources.md","filePath":"zh/guide/sources.md","lastUpdated":1793111003000}'),o={name:"zh/guide/sources.md"};function n(l,e,h,s,p,i){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to &quot;数据源&quot;">​</a></h1><p>选择适合研究问题的文献索引，不同提供方的覆盖、元数据、访问要求和筛选能力并不相同。</p><h2 id="数据源目录" tabindex="-1">数据源目录 <a class="header-anchor" href="#数据源目录" aria-label="Permalink to &quot;数据源目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据源</th><th>社区版</th><th>在线版 BYOK</th><th>侧重</th></tr></thead><tbody><tr><td><a href="https://openalex.org/" target="_blank" rel="noreferrer">OpenAlex</a></td><td>建议配置 Key</td><td>必须配置 Key</td><td>广泛学术发现与引用扩展</td></tr><tr><td><a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a></td><td>无需 Key</td><td>无需 Key</td><td>科学预印本</td></tr><tr><td><a href="https://www.crossref.org/" target="_blank" rel="noreferrer">Crossref</a></td><td>无需 Key</td><td>无需 Key</td><td>DOI 与出版元数据</td></tr><tr><td><a href="https://www.semanticscholar.org/" target="_blank" rel="noreferrer">Semantic Scholar</a></td><td>Key 可选</td><td>必须配置 Key</td><td>论文与学术图谱元数据</td></tr><tr><td><a href="https://pubmed.ncbi.nlm.nih.gov/" target="_blank" rel="noreferrer">PubMed</a></td><td>NCBI Key 可选</td><td>必须配置 Key</td><td>生物医学与生命科学</td></tr><tr><td>Google Scholar / <a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper</a></td><td>必须配置 Serper Key</td><td>必须配置 Key</td><td>通过受支持 API 检索 Scholar</td></tr><tr><td>PaperHub 计算机顶会</td><td>无需 Key</td><td>无需 Key</td><td>PaperHub 提供的顶会集合，并补充 OpenReview 上已录用的论文</td></tr><tr><td><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">Web of Science Starter</a></td><td>需要 Clarivate Key</td><td>必须配置 Key</td><td>受支持的 WoS 集合</td></tr><tr><td><a href="https://www.wanfangdata.com.cn/" target="_blank" rel="noreferrer">万方数据</a></td><td>需要万方 AppKey</td><td>必须自备 Key</td><td>中文期刊论文、学位论文和会议论文</td></tr><tr><td><a href="https://www.ncpssd.cn/" target="_blank" rel="noreferrer">国家哲学社会科学学术期刊数据库</a></td><td>无需 Key</td><td>暂不提供</td><td>中文哲学社会科学期刊</td></tr><tr><td><a href="https://www.yiigle.com/" target="_blank" rel="noreferrer">中华医学期刊库</a></td><td>无需 Key</td><td>暂不提供</td><td>中华医学会系列期刊的题录和摘要</td></tr></tbody></table><p>PaperSeek 服务的数据源访问由 PaperSeek 管理，Web of Science 和万方数据除外：站点不提供这两个库的密钥，即使使用 PaperSeek 服务，也需要在<strong>设置 → 模型服务</strong>中保存自己的密钥。社区版按上表允许匿名访问或使用可选密钥；在线版 BYOK 是单独的访问策略，在设置中填写并保存数据源密钥；除 arXiv、Crossref、PaperHub 等无需密钥的数据源外，其余数据源（包括 OpenAlex、PubMed、Semantic Scholar）都必须提供密钥。模型 Key 与数据源 Key 并不通用。</p><h2 id="中文数据库" tabindex="-1">中文数据库 <a class="header-anchor" href="#中文数据库" aria-label="Permalink to &quot;中文数据库&quot;">​</a></h2><p>在万方数据、国家哲学社会科学学术期刊数据库和中华医学期刊库检索时，检索计划、概念组和每一条检索式都用中文构建，使用这些数据库实际标引的中文学术用语；无论你用中文还是英文提问都是如此。SGLT2、COVID-19 这类通用缩写会原样保留。</p><p>三个数据库的检索式写法各不相同：</p><table tabindex="0"><thead><tr><th>数据库</th><th>PaperSeek 发送的检索式</th></tr></thead><tbody><tr><td>万方数据</td><td>万方 PQ 表达式，例如 <code>(数字治理 OR 数字化治理) AND 乡村振兴</code>；只有核心概念需要时才加 标题:、关键词:、摘要: 字段</td></tr><tr><td>国家哲学社会科学学术期刊数据库</td><td>用 AND、OR、NOT 连接的中文检索词；PaperSeek 会在题名、主题词和摘要中检索每个词</td></tr><tr><td>中华医学期刊库</td><td>2–4 个用空格分隔的中文词。该库要求所有词同时出现，不支持 OR，所以每个概念只保留一个词</td></tr></tbody></table><p>这些数据库返回中文题名、作者、刊名和摘要。国家哲学社会科学学术期刊数据库和中华医学期刊库只提供题录和摘要，PaperSeek 不会下载其全文。万方需要 AppKey（<a href="https://ai.wfdata.com/skills/api" target="_blank" rel="noreferrer">申请地址</a>），可在<strong>设置 → 数据源</strong>中填写，或设置环境变量 <code>PAPERSEEK_WANFANG_API_KEY</code>。</p><h2 id="配置与测试数据源" tabindex="-1">配置与测试数据源 <a class="header-anchor" href="#配置与测试数据源" aria-label="Permalink to &quot;配置与测试数据源&quot;">​</a></h2><p>打开<strong>设置 → 数据源</strong>，点击来源所在行的<strong>配置</strong>或<strong>配置密钥</strong>，填写密钥和选项后点击<strong>保存</strong>。</p><p>此弹窗中的<strong>测试连接</strong>也会先保存当前密钥和选项，再测试。若保存失败，则不执行测试；保存成功后，即使测试失败或随后取消弹窗，也不会撤销保存。如需修改或清除已保存的密钥，请重新打开来源配置。列表中的<strong>测试</strong>和<strong>全部测试</strong>使用已配置的凭据，不会保存表单草稿。模型连接草稿的测试不会保存，详见<a href="./models">模型与排序</a>。</p><h2 id="申请凭据" tabindex="-1">申请凭据 <a class="header-anchor" href="#申请凭据" aria-label="Permalink to &quot;申请凭据&quot;">​</a></h2><ul><li><a href="https://openalex.org/settings/api" target="_blank" rel="noreferrer">OpenAlex API 设置</a>。</li><li><a href="https://www.semanticscholar.org/product/api#api-key-form" target="_blank" rel="noreferrer">Semantic Scholar Key 申请</a>。</li><li><a href="https://www.ncbi.nlm.nih.gov/books/NBK25497/" target="_blank" rel="noreferrer">NCBI API 指南</a>。</li><li><a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper 账户</a>。</li><li><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">WoS Starter 应用</a>。</li><li><a href="https://ai.wfdata.com/skills/api" target="_blank" rel="noreferrer">万方 AppKey 申请</a>。</li></ul><p>上游订阅和速率限制，与 PaperSeek 账户及积分分别管理。</p><h2 id="零结果与临时故障" tabindex="-1">零结果与临时故障 <a class="header-anchor" href="#零结果与临时故障" aria-label="Permalink to &quot;零结果与临时故障&quot;">​</a></h2><p>检索返回零篇论文时，PaperSeek 最多再尝试两次。每次都会参考之前的检索式及其结果数，以及数据源反馈（例如 PubMed 未识别的短语），调整术语或可选限制。检索式执行前，另一次模型检查必须确认核心概念、必要关系和明确限制得到保留。这个检查不保证论文相关性，仍需查看检索过程和结果。没有合适检索式通过检查、数据源依然没有命中，或补充检索时无法连接数据源，检索都会以零结果结束并给出原因，不会默默删除研究必需条件；领域筛选始终继续应用。</p><p>调整任何检索时，如果模型给出的检索式之前已经执行过，会把之前的结果告诉模型并再请求一次，仍然重复才停止调整。</p><p>限流和异常接口响应会作为数据源问题报告，不会当作零命中。请求采用有上限的重试，并遵守 <code>Retry-After</code>；一般故障约 1 秒后重试，限流则等待更久。同一 PaperSeek 进程内运行的所有任务，对相同数据源和凭据共享节流与冷却时间，重试也受同样控制。例如无论同时运行多少个检索，arXiv 都是每 3 秒一次请求；Semantic Scholar 批量检索接口的冷却不会阻断普通相关性检索。后续检索式调整或翻页失败时，保留已有候选；辅助通道不可用则带警告继续。不同 worker 进程或其他应用仍可能共享上游账户配额，因此重试不能保证数据源恢复。</p><h2 id="网络代理" tabindex="-1">网络代理 <a class="header-anchor" href="#网络代理" aria-label="Permalink to &quot;网络代理&quot;">​</a></h2><p>如果你的网络无法直接访问某个数据源或模型服务，或者数据源对你的网络地址限速，可以在 <strong>设置 › 通用 › 网络代理</strong> 中设置代理，并选择哪些请求走代理：大模型请求、按网络地址限速的数据源（arXiv、Crossref、PaperHub、OpenReview、国家哲学社会科学学术期刊数据库、中华医学期刊库、期刊分区数据下载，以及未填写密钥的 PubMed 和 OpenAlex）、其他数据源。代理不会增加密钥的额度。详情及对应的环境变量见<a href="./../reference/configuration#网络代理">网络代理</a>。</p><h2 id="领域与分类" tabindex="-1">领域与分类 <a class="header-anchor" href="#领域与分类" aria-label="Permalink to &quot;领域与分类&quot;">​</a></h2><p>OpenAlex 使用受支持的学科选项，语义通道按支持的方式执行筛选；arXiv 使用 Category；WoS 学科与 WoS 数据库选择独立。其他来源使用文本领域提示。</p><p>限制领域可能排除跨学科文献，除非研究设计要求，否则可先不限制。</p><h2 id="元数据缺失" tabindex="-1">元数据缺失 <a class="header-anchor" href="#元数据缺失" aria-label="Permalink to &quot;元数据缺失&quot;">​</a></h2><p>记录可能没有摘要、年份、引用数或开放 PDF。信息缺失不是质量判断。</p><p>1.0.0-beta5 不再提供独立的跨源摘要补全或引用数补全开关。写综述时请选择摘要信息充分的文献。</p><h2 id="多-key-轮询" tabindex="-1">多 Key 轮询 <a class="header-anchor" href="#多-key-轮询" aria-label="Permalink to &quot;多 Key 轮询&quot;">​</a></h2><p>OpenAlex 与 Serper 支持用空白、逗号或分号分隔的 Key 池。请求会轮换起始 Key，鉴权失败与临时错误分别处理。</p><p>轮询不会改变提供方的条款，也不保证仍有余额，详见<a href="./../reference/configuration">配置参考</a>。</p>',31)])])}const b=t(o,[["render",n]]);export{f as __pageData,b as default};
